1	package com.example.starter.service;
2	
3	import com.example.starter.domain.UnsealOrder;
4	import com.example.starter.domain.UnsealQuotaUsage;
5	import com.example.starter.domain.Valve;
6	import com.example.starter.domain.ValveSeal;
7	import com.example.starter.repository.UnsealOrderRepository;
8	import com.example.starter.repository.UnsealQuotaUsageRepository;
9	import com.example.starter.repository.ValveRepository;
10	import com.example.starter.repository.ValveSealRepository;
11	import com.example.starter.repository.ValveVersionRepository;
12	import org.springframework.dao.DuplicateKeyException;
13	import org.springframework.stereotype.Service;
14	import org.springframework.transaction.annotation.Transactional;
15	
16	import java.time.Clock;
17	import java.time.Instant;
18	import java.util.List;
19	
20	/**
21	 * 铅封管理：登记、临时解封批准、撤销、复封与额度轨迹查询。
22	 * 锁顺序约定：station → valve → unseal，所有铅封/解封变更均在阀门行锁内串行。
23	 */
24	@Service
25	public class SealService {
26	
27	    /** 临时解封单的调节额度上限：最多两次。 */
28	    public static final int UNSEAL_QUOTA_TOTAL = 2;
29	
30	    private final ValveRepository valveRepository;
31	    private final ValveSealRepository sealRepository;
32	    private final UnsealOrderRepository unsealRepository;
33	    private final UnsealQuotaUsageRepository usageRepository;
34	    private final ValveVersionRepository versionRepository;
35	    private final Clock clock;
36	
37	    public SealService(ValveRepository valveRepository,
38	                       ValveSealRepository sealRepository,
39	                       UnsealOrderRepository unsealRepository,
40	                       UnsealQuotaUsageRepository usageRepository,
41	                       ValveVersionRepository versionRepository,
42	                       Clock clock) {
43	        this.valveRepository = valveRepository;
44	        this.sealRepository = sealRepository;
45	        this.unsealRepository = unsealRepository;
46	        this.usageRepository = usageRepository;
47	        this.versionRepository = versionRepository;
48	        this.clock = clock;
49	    }
50	
51	    /**
52	     * 铅封登记：登记唯一铅封号、当前开度版本与封存时刻，版本从 1 开始。
53	     * 完整铅封生效后新的调节令必须拒绝（由调节服务在事务内重查）。
54	     */
55	    @Transactional
56	    public ValveSeal registerSeal(long valveId, String requestId, String sealNo, int valveVersion) {
57	        String fingerprint = Fingerprints.of("SEAL", requestId, String.valueOf(valveId),
58	                sealNo, String.valueOf(valveVersion));
59	        var existing = sealRepository.findByRequestId(requestId);
60	        if (existing.isPresent()) {
61	            return replayOrConflict(existing.get(), fingerprint);
62	        }
63	        valveRepository.lockById(valveId)
64	                .orElseThrow(() -> new NotFoundException("阀门不存在: valveId=" + valveId));
65	        // 持锁后重查幂等键：并发下同键请求在前序事务提交后按重放处理。
66	        var existingAfterLock = sealRepository.findByRequestId(requestId);
67	        if (existingAfterLock.isPresent()) {
68	            return replayOrConflict(existingAfterLock.get(), fingerprint);
69	        }
70	        int currentVersion = versionRepository.maxVersionNo(valveId);
71	        if (valveVersion != currentVersion) {
72	            throw new UnprocessableException("登记的开度版本与当前版本不一致: 当前=" + currentVersion
73	                    + ", 请求=" + valveVersion);
74	        }
75	        if (sealRepository.findActiveByValveId(valveId).isPresent()) {
76	            throw new UnprocessableException("阀门已存在完整铅封，须先复封: valveId=" + valveId);
77	        }
78	        if (sealRepository.findBySealNo(sealNo).isPresent()) {
79	            throw new ConflictException("铅封号已存在: sealNo=" + sealNo);
80	        }
81	        ValveSeal seal = new ValveSeal(0, valveId, sealNo, currentVersion,
82	                ValveSeal.SealStatus.ACTIVE, 1, clock.instant(), null, requestId, fingerprint);
83	        try {
84	            long id = sealRepository.insert(seal);
85	            return sealRepository.findById(id).orElseThrow();
86	        } catch (DuplicateKeyException e) {
87	            // 并发下唯一约束兜底：同键重放，异键同铅封号冲突。
88	            return sealRepository.findByRequestId(requestId)
89	                    .map(s -> replayOrConflict(s, fingerprint))
90	                    .orElseThrow(() -> new ConflictException("铅封号已存在: sealNo=" + sealNo));
91	        }
92	    }
93	
94	    /**
95	     * 临时解封批准：引用铅封号及阀门版本，两名不同授权人共同确认，
96	     * 固定 UTC 半开窗口 [windowStart, windowEnd) 与固定两次调节额度；生效不改变开度。
97	     */
98	    @Transactional
99	    public UnsealOrder approveUnseal(long sealId, String requestId, int expectedVersion,
100	                                     int valveVersion, String approverA, String approverB,
101	                                     Instant windowStart, Instant windowEnd) {
102	        String fingerprint = Fingerprints.of("UNSEAL", requestId, String.valueOf(sealId),
103	                String.valueOf(expectedVersion), String.valueOf(valveVersion),
104	                approverA, approverB, windowStart.toString(), windowEnd.toString());
105	        var existing = unsealRepository.findByRequestId(requestId);
106	        if (existing.isPresent()) {
107	            return replayOrConflict(existing.get(), fingerprint);
108	        }
109	        ValveSeal seal = sealRepository.findById(sealId)
110	                .orElseThrow(() -> new NotFoundException("铅封不存在: sealId=" + sealId));
111	        long sealValveId = seal.valveId();
112	        valveRepository.lockById(sealValveId)
113	                .orElseThrow(() -> new NotFoundException("阀门不存在: valveId=" + sealValveId));
114	        // 持锁后重查幂等键与铅封状态。
115	        var existingAfterLock = unsealRepository.findByRequestId(requestId);
116	        if (existingAfterLock.isPresent()) {
117	            return replayOrConflict(existingAfterLock.get(), fingerprint);
118	        }
119	        seal = sealRepository.findById(sealId).orElseThrow();
120	        if (seal.status() != ValveSeal.SealStatus.ACTIVE) {
121	            throw new UnprocessableException("铅封已被复封替换，不得解封: sealId=" + sealId);
122	        }
123	        if (seal.version() != expectedVersion) {
124	            throw new ConflictException("铅封版本不一致: 当前=" + seal.version()
125	                    + ", expectedVersion=" + expectedVersion);
126	        }
127	        if (approverA.equals(approverB)) {
128	            throw new UnprocessableException("解封须两名不同授权人共同确认: " + approverA);
129	        }
130	        if (!windowStart.isBefore(windowEnd)) {
131	            throw new UnprocessableException("解封窗口非法：起点须早于终点(UTC): "
132	                    + windowStart + " ~ " + windowEnd);
133	        }
134	        int currentVersion = versionRepository.maxVersionNo(seal.valveId());
135	        if (valveVersion != currentVersion) {
136	            throw new UnprocessableException("引用的阀门版本与当前版本不一致: 当前=" + currentVersion
137	                    + ", 请求=" + valveVersion);
138	        }
139	        if (unsealRepository.findActiveBySealId(sealId).isPresent()) {
140	            throw new UnprocessableException("铅封已存在有效解封单: sealId=" + sealId);
141	        }
142	        UnsealOrder order = new UnsealOrder(0, sealId, seal.valveId(), seal.sealNo(),
143	                currentVersion, approverA, approverB, windowStart, windowEnd,
144	                UNSEAL_QUOTA_TOTAL, 0, UnsealOrder.UnsealStatus.ACTIVE, 1,
145	                clock.instant(), null, requestId, fingerprint, null, null);
146	        try {
147	            long id = unsealRepository.insert(order);
148	            return unsealRepository.findById(id).orElseThrow();
149	        } catch (DuplicateKeyException e) {
150	            return unsealRepository.findByRequestId(requestId)
151	                    .map(o -> replayOrConflict(o, fingerprint))
152	                    .orElseThrow(() -> e);
153	        }
154	    }
155	
156	    /**
157	     * 撤销解封单：仅禁止新调节，不回拨已改开度；重复同键撤销重放首次结果。
158	     */
159	    @Transactional
160	    public UnsealOrder revokeUnseal(long unsealId, String requestId, int expectedVersion) {
161	        String fingerprint = Fingerprints.of("REVOKE", requestId, String.valueOf(unsealId),
162	                String.valueOf(expectedVersion));
163	        UnsealOrder order = unsealRepository.findById(unsealId)
164	                .orElseThrow(() -> new NotFoundException("解封单不存在: unsealId=" + unsealId));
165	        if (order.status() == UnsealOrder.UnsealStatus.REVOKED) {
166	            return replayRevoke(order, requestId, fingerprint);
167	        }
168	        // 行锁串行化撤销与受控调节的额度消费。
169	        order = unsealRepository.lockById(unsealId).orElseThrow();
170	        if (order.status() == UnsealOrder.UnsealStatus.REVOKED) {
171	            return replayRevoke(order, requestId, fingerprint);
172	        }
173	        if (order.status() != UnsealOrder.UnsealStatus.ACTIVE) {
174	            throw new ConflictException("解封单已终结（复封），不允许撤销: unsealId=" + unsealId);
175	        }
176	        if (order.version() != expectedVersion) {
177	            throw new ConflictException("解封单版本不一致: 当前=" + order.version()
178	                    + ", expectedVersion=" + expectedVersion);
179	        }
180	        int updated = unsealRepository.revoke(unsealId, expectedVersion, clock.instant(),
181	                requestId, fingerprint);
182	        if (updated != 1) {
183	            throw new ConflictException("解封单并发变更，撤销失败: unsealId=" + unsealId);
184	        }
185	        return unsealRepository.findById(unsealId).orElseThrow();
186	    }
187	
188	    /**
189	     * 复封：两名不同人员核对当前开度版本并登记新铅封号，
190	     * 原子终结旧解封权限，旧铅封转入历史封号链。
191	     */
192	    @Transactional
193	    public ValveSeal reseal(long valveId, String requestId, int expectedVersion,
194	                            String newSealNo, String checkerA, String checkerB, int valveVersion) {
195	        String fingerprint = Fingerprints.of("RESEAL", requestId, String.valueOf(valveId),
196	                String.valueOf(expectedVersion), newSealNo, checkerA, checkerB,
197	                String.valueOf(valveVersion));
198	        var existing = sealRepository.findByRequestId(requestId);
199	        if (existing.isPresent()) {
200	            return replayOrConflict(existing.get(), fingerprint);
201	        }
202	        valveRepository.lockById(valveId)
203	                .orElseThrow(() -> new NotFoundException("阀门不存在: valveId=" + valveId));
204	        var existingAfterLock = sealRepository.findByRequestId(requestId);
205	        if (existingAfterLock.isPresent()) {
206	            return replayOrConflict(existingAfterLock.get(), fingerprint);
207	        }
208	        ValveSeal active = sealRepository.findActiveByValveId(valveId)
209	                .orElseThrow(() -> new UnprocessableException("阀门无完整铅封，无需复封: valveId=" + valveId));
210	        if (active.version() != expectedVersion) {
211	            throw new ConflictException("铅封版本不一致: 当前=" + active.version()
212	                    + ", expectedVersion=" + expectedVersion);
213	        }
214	        if (checkerA.equals(checkerB)) {
215	            throw new UnprocessableException("复封须两名不同人员核对: " + checkerA);
216	        }
217	        int currentVersion = versionRepository.maxVersionNo(valveId);
218	        if (valveVersion != currentVersion) {
219	            throw new UnprocessableException("核对的开度版本与当前版本不一致: 当前=" + currentVersion
220	                    + ", 请求=" + valveVersion);
221	        }
222	        if (sealRepository.findBySealNo(newSealNo).isPresent()) {
223	            throw new ConflictException("铅封号已存在: sealNo=" + newSealNo);
224	        }
225	        Instant now = clock.instant();
226	        // 原子终结旧解封权限与旧铅封，再登记新铅封；任一失败整体回滚。
227	        unsealRepository.closeActiveBySealId(active.id());
228	        int updated = sealRepository.markResealed(active.id(), expectedVersion, now);
229	        if (updated != 1) {
230	            throw new ConflictException("铅封并发变更，复封失败: sealId=" + active.id());
231	        }
232	        ValveSeal newSeal = new ValveSeal(0, valveId, newSealNo, currentVersion,
233	                ValveSeal.SealStatus.ACTIVE, 1, now, null, requestId, fingerprint);
234	        try {
235	            long id = sealRepository.insert(newSeal);
236	            return sealRepository.findById(id).orElseThrow();
237	        } catch (DuplicateKeyException e) {
238	            return sealRepository.findByRequestId(requestId)
239	                    .map(s -> replayOrConflict(s, fingerprint))
240	                    .orElseThrow(() -> new ConflictException("铅封号已存在: sealNo=" + newSealNo));
241	        }
242	    }
243	
244	    /**
245	     * 查询阀门完整封号链（含历史），按登记先后升序。
246	     */
247	    @Transactional(readOnly = true)
248	    public List<ValveSeal> getSealChain(long valveId) {
249	        valveRepository.findById(valveId)
250	                .orElseThrow(() -> new NotFoundException("阀门不存在: valveId=" + valveId));
251	        return sealRepository.findByValveId(valveId);
252	    }
253	
254	    /**
255	     * 查询阀门当前完整有效的铅封。
256	     */
257	    @Transactional(readOnly = true)
258	    public ValveSeal getActiveSeal(long valveId) {
259	        valveRepository.findById(valveId)
260	                .orElseThrow(() -> new NotFoundException("阀门不存在: valveId=" + valveId));
261	        return sealRepository.findActiveByValveId(valveId)
262	                .orElseThrow(() -> new NotFoundException("阀门无完整铅封: valveId=" + valveId));
263	    }
264	
265	    /**
266	     * 查询解封单详情。
267	     */
268	    @Transactional(readOnly = true)
269	    public UnsealOrder getUnseal(long unsealId) {
270	        return unsealRepository.findById(unsealId)
271	                .orElseThrow(() -> new NotFoundException("解封单不存在: unsealId=" + unsealId));
272	    }
273	
274	    /**
275	     * 查询解封单的额度消费轨迹。
276	     */
277	    @Transactional(readOnly = true)
278	    public List<UnsealQuotaUsage> getQuotaTrail(long unsealId) {
279	        unsealRepository.findById(unsealId)
280	                .orElseThrow(() -> new NotFoundException("解封单不存在: unsealId=" + unsealId));
281	        return usageRepository.findByUnsealId(unsealId);
282	    }
283	
284	    private UnsealOrder replayRevoke(UnsealOrder order, String requestId, String fingerprint) {
285	        if (!requestId.equals(order.revokeRequestId())) {
286	            throw new ConflictException("解封单已被其他请求撤销: unsealId=" + order.id());
287	        }
288	        if (!order.revokeFingerprint().equals(fingerprint)) {
289	            throw new ConflictException("同键异参，返回 409: requestId=" + requestId);
290	        }
291	        return order;
292	    }
293	
294	    private ValveSeal replayOrConflict(ValveSeal existing, String fingerprint) {
295	        if (!existing.fingerprint().equals(fingerprint)) {
296	            throw new ConflictException("同键异参，返回 409: requestId=" + existing.requestId());
297	        }
298	        return existing;
299	    }
300	
301	    private UnsealOrder replayOrConflict(UnsealOrder existing, String fingerprint) {
302	        if (!existing.fingerprint().equals(fingerprint)) {
303	            throw new ConflictException("同键异参，返回 409: requestId=" + existing.requestId());
304	        }
305	        return existing;
306	    }
307	}
