        return adjustmentService.getAssessmentByTask(taskId);
    }

    /**
     * 归档：终态，重复归档幂等成功。
     */
    @PostMapping("/{taskId}/archive")
    public AdjustmentTask archive(@PathVariable long taskId) {
        return adjustmentService.archive(taskId);
    }
}

