1	package com.example.starter;
2	
3	import com.example.starter.domain.AdjustmentTask;
4	import com.example.starter.domain.UnsealOrder;
5	import com.example.starter.domain.ValveSeal;
6	import com.example.starter.service.AdjustmentService;
7	import com.example.starter.service.SealService;
8	import org.junit.jupiter.api.Test;
9	import org.springframework.beans.factory.annotation.Autowired;
10	
11	import java.math.BigDecimal;
12	import java.time.Duration;
13	import java.util.ArrayList;
14	import java.util.List;
15	import java.util.concurrent.CountDownLatch;
16	import java.util.concurrent.ExecutorService;
17	import java.util.concurrent.Executors;
18	import java.util.concurrent.Future;
19	import java.util.concurrent.TimeUnit;
20	import java.util.function.IntFunction;
21	
22	import static org.assertj.core.api.Assertions.assertThat;
23	
24	/**
25	 * 铅封并发边界：同键受控调节唯一消费额度；复封与受控调节竞争唯一，不留撕裂状态。
26	 */
27	class SealConcurrencyTest extends IntegrationTestBase {
28	
29	    @Autowired
30	    private SealService sealService;
31	    @Autowired
32	    private AdjustmentService adjustmentService;
33	
34	    private record Outcome(Object result, Throwable error) {
35	    }
36	
37	    private List<Outcome> runConcurrently(int threads, IntFunction<Object> action)
38	            throws InterruptedException {
39	        ExecutorService pool = Executors.newFixedThreadPool(threads);
40	        CountDownLatch gate = new CountDownLatch(1);
41	        List<Future<Outcome>> futures = new ArrayList<>();
42	        for (int i = 0; i < threads; i++) {
43	            final int index = i;
44	            futures.add(pool.submit(() -> {
45	                gate.await(5, TimeUnit.SECONDS);
46	                try {
47	                    return new Outcome(action.apply(index), null);
48	                } catch (Throwable e) {
49	                    return new Outcome(null, e);
50	                }
51	            }));
52	        }
53	        gate.countDown();
54	        List<Outcome> outcomes = new ArrayList<>();
55	        for (Future<Outcome> future : futures) {
56	            try {
57	                outcomes.add(future.get(30, TimeUnit.SECONDS));
58	            } catch (Exception e) {
59	                throw new IllegalStateException("并发用例执行超时或失败", e);
60	            }
61	        }
62	        pool.shutdownNow();
63	        return outcomes;
64	    }
65	
66	    private int quotaUsedOf(long unsealId) {
67	        Integer used = jdbc.queryForObject(
68	                "SELECT quota_used FROM unseal_order WHERE id = ?", Integer.class, unsealId);
69	        return used == null ? -1 : used;
70	    }
71	
72	    @Test
73	    void 同键并发受控调节唯一受理且只消费一次额度() throws Exception {
74	        submitReadings(40.00, 42.50, 41.00, 41.00);
75	        ValveSeal seal = sealService.registerSeal(1L, "req-seal-cc", "SEAL-CC", 0);
76	        UnsealOrder order = sealService.approveUnseal(seal.id(), "req-u-cc", 1, 0,
77	                "张三", "李四", T0, T0.plus(Duration.ofHours(2)));
78	
79	        List<Outcome> outcomes = runConcurrently(4,
80	                i -> adjustmentService.issueControlledAdjustment(
81	                        order.id(), "req-ca-cc", 1, new BigDecimal("5")));
82	
83	        assertThat(outcomes).allMatch(o -> o.error() == null);
84	        long distinctTaskIds = outcomes.stream()
85	                .map(o -> ((AdjustmentTask) o.result()).id()).distinct().count();
86	        assertThat(distinctTaskIds).isEqualTo(1);
87	        // 最终数据：唯一任务、唯一版本、唯一额度消费
88	        assertThat(countOf("adjustment_task")).isEqualTo(1);
89	        assertThat(countOf("valve_opening_version")).isEqualTo(1);
90	        assertThat(quotaUsedOf(order.id())).isEqualTo(1);
91	        assertThat(countOf("unseal_quota_usage")).isEqualTo(1);
92	        assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("55.00"));
93	    }
94	
95	    @Test
96	    void 复封与受控调节竞争唯一且不留撕裂状态() throws Exception {
97	        for (int round = 0; round < 3; round++) {
98	            resetDatabase();
99	            submitReadings(40.00, 42.50, 41.00, 41.00);
100	            ValveSeal seal = sealService.registerSeal(1L, "req-seal-race-" + round, "SEAL-RACE-" + round, 0);
101	            UnsealOrder order = sealService.approveUnseal(seal.id(), "req-u-race-" + round, 1, 0,
102	                    "张三", "李四", T0, T0.plus(Duration.ofHours(2)));
103	            long unsealId = order.id();
104	            final int roundNo = round;
105	
106	            List<Outcome> outcomes = runConcurrently(2, i -> i == 0
107	                    ? adjustmentService.issueControlledAdjustment(
108	                            unsealId, "req-ca-race-" + roundNo, 1, new BigDecimal("5"))
109	                    : sealService.reseal(1L, "req-rs-race-" + roundNo, 1,
110	                            "SEAL-RACE-NEW-" + roundNo, "甲", "乙", 0));
111	
112	            long adjustOk = outcomes.stream()
113	                    .filter(o -> o.result() instanceof AdjustmentTask).count();
114	            long resealOk = outcomes.stream()
115	                    .filter(o -> o.result() instanceof ValveSeal).count();
116	            // 竞争唯一：恰有一个获胜（调节先则复封因开度版本已变被拒；复封先则调节因解封终结被拒）
117	            assertThat(adjustOk + resealOk).isEqualTo(1);
118	
119	            if (adjustOk == 1) {
120	                // 调节先提交：额度已消费、版本已追加，复封被拒绝，旧解封仍有效
121	                assertThat(quotaUsedOf(unsealId)).isEqualTo(1);
122	                assertThat(countOf("valve_opening_version")).isEqualTo(1);
123	                assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("55.00"));
124	                assertThat(sealService.getUnseal(unsealId).status())
125	                        .isEqualTo(UnsealOrder.UnsealStatus.ACTIVE);
126	            } else {
127	                // 复封先提交：旧解封已终结，不得再追加调节版本，额度未消费
128	                assertThat(quotaUsedOf(unsealId)).isEqualTo(0);
129	                assertThat(countOf("valve_opening_version")).isEqualTo(0);
130	                assertThat(openingOf(1L)).isEqualByComparingTo(new BigDecimal("50.00"));
131	                assertThat(sealService.getUnseal(unsealId).status())
132	                        .isEqualTo(UnsealOrder.UnsealStatus.CLOSED);
133	                assertThat(sealService.getActiveSeal(1L).sealNo())
134	                        .isEqualTo("SEAL-RACE-NEW-" + round);
135	            }
136	        }
137	    }
138	}
